"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[61379],{28453:(e,t,o)=>{o.d(t,{R:()=>s,x:()=>r});var n=o(96540);const a={},i=n.createContext(a);function s(e){const t=n.useContext(i);return n.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),n.createElement(i.Provider,{value:t},e.children)}},72047:(e,t,o)=>{o.r(t),o.d(t,{assets:()=>c,contentTitle:()=>r,default:()=>d,frontMatter:()=>s,metadata:()=>n,toc:()=>l});const n=JSON.parse('{"id":"tangfen/workandcommodity","title":"","description":"In my post \\"[Dushulang], Ququ Xiansheng, Falanxi Dacai Shifu, and Others \\"The labor dimension is likewise a pseudo-concept. Only when examining labor from the perspective of value measurement can we say that the dimension of the value of the labor-power commodity is likewise the currency dimension.\\" This was stated so clearly, yet some people still don\'t understand and keep asking all day: how did labor turn into the labor-power commodity? From this it\'s clear that these people can\'t even understand the relationship between labor and the labor-power commodity!","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/workandcommodity.md","sourceDirName":"tangfen","slug":"/tangfen/workandcommodity","permalink":"/tangfen/workandcommodity","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"workandcommodity","title":"","hide_table_of_contents":true},"sidebar":"tangfenSidebar","previous":{"title":"\u201c\u52b3\u52a8\u201d\u548c\u201c\u4ef7\u503c\u201d\uff0c\u96be\u9053[\u8bfb\u4e66\u72fc]\u7b49\u8fde\u4e24\u8005\u95f4\u7684\u5173\u7cfb\u90fd\u641e\u4e0d\u61c2\uff1f","permalink":"/tangfen/workandvalues"},"next":{"title":"[\u8bfb\u4e66\u72fc]\u3001\u533a\u533a\u5148\u751f\u3001\u6cd5\u5170\u897f\u5927\u83dc\u5e08\u5085\u7b49\u7b49\uff0c\u8bf7\u4e0d\u8981\u7ee7\u7eed\u52b3\u52a8\u91cf\u7eb2\u7684\u4f2a\u6982\u5ff5\uff01","permalink":"/tangfen/falseconcept"}}');var a=o(74848),i=o(28453);const s={id:"workandcommodity",title:"",hide_table_of_contents:!0},r="[Dushulang] and Others, Can You Really Not Even Understand the Relationship Between Labor and the Labor-Power Commodity?",c={},l=[];function h(e){const t={h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"dushulang-and-others-can-you-really-not-even-understand-the-relationship-between-labor-and-the-labor-power-commodity",children:"[Dushulang] and Others, Can You Really Not Even Understand the Relationship Between Labor and the Labor-Power Commodity?"})}),"\n",(0,a.jsx)(t.p,{children:"In my post \"[Dushulang], Ququ Xiansheng, Falanxi Dacai Shifu, and Others: Please Stop Perpetuating the Pseudo-Concept of 'Labor Dimension'!\" I wrote: \"The labor dimension is likewise a pseudo-concept. Only when examining labor from the perspective of value measurement can we say that the dimension of the value of the labor-power commodity is likewise the currency dimension.\" This was stated so clearly, yet some people still don't understand and keep asking all day: how did labor turn into the labor-power commodity? From this it's clear that these people can't even understand the relationship between labor and the labor-power commodity!"}),"\n",(0,a.jsx)(t.p,{children:'In that post, I already anticipated that these people might not understand these relationships, so I specifically wrote: "I ask those who either oppose or support Marx to first get clear on several concepts: labor, labor-power, and the labor-power commodity." So let me discuss the relationship between labor and the labor-power commodity.'}),"\n",(0,a.jsx)(t.p,{children:"In Marx, all categories are historical, holistic, concrete, and real. That is, no category is a priori or unchanging. In different historical periods, categories evolve into different historical forms. In Marx, this is a very basic piece of common knowledge."}),"\n",(0,a.jsx)(t.p,{children:"For example, the category of the labor-power commodity had no meaning before capitalist society. We cannot discuss anything about the labor-power commodity category, because outside the historical stage of capitalist society, it is nothing at all. Similarly, the labor category spans all historical periods of humanity, but in the specific historical stage of capitalist society, it manifests particular content. So discussing categories divorced from historical periods has no meaning in Marx. Similarly, for the categories of value, commodity, capital, and currency -- before we discuss them, there is a basic Marxian premise: we discuss them under the historical conditions of capitalism. Not in the vague, a priori way people nowadays discuss these concepts."}),"\n",(0,a.jsx)(t.p,{children:"Value is an attribute specific to commodities. That is, when we measure a phenomenon from the perspective of value, there is a basic premise: this phenomenon is capable of being measured by value. Labor is not unconditionally measurable by value. Only under the historical conditions of capitalism does value measurement of labor become possible. That is, the premise for labor to be measured by value is the commodification of labor -- that is, the emergence of the labor-power commodity. Labor-power is not a priori a commodity; it becomes a commodity only under capitalist historical conditions."}),"\n",(0,a.jsx)(t.p,{children:"The labor-power commodity category is the historical form of the labor category under capitalist conditions. Therefore, it's not hard to understand the sentence: \"The labor dimension is likewise a pseudo-concept. Only when examining labor from the perspective of value measurement can we say that the dimension of the value of the labor-power commodity is likewise the currency dimension.\" Because once labor can be examined from the perspective of value measurement, labor must necessarily manifest in the capitalist historical form of the labor-power commodity. Otherwise, unconditionally claiming to examine labor from the perspective of value measurement has no meaning. Precisely because many people can't figure out the relationship between labor and the labor-power commodity, they can't understand the meaning of this sentence."}),"\n",(0,a.jsx)(t.p,{children:"Marx's theory is a rigorous system. Please do not comment on it carelessly!"})]})}function d(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(h,{...e})}):h(e)}}}]);